export const CHROME_LOCALES = Object.freeze(["en", "it", "es", "fr"]);

function normalizedLocale(value) {
  const language = String(value || "").replaceAll("_", "-").split("-")[0].toLowerCase();
  return CHROME_LOCALES.includes(language) ? language : "en";
}

const browserPreferences = globalThis.navigator?.languages || [globalThis.navigator?.language];
const firstSupported = browserPreferences.find((candidate) =>
  CHROME_LOCALES.includes(String(candidate || "").replaceAll("_", "-").split("-")[0].toLowerCase())
);
let activeLocale = normalizedLocale(firstSupported);

export function getChromeLocale() { return activeLocale; }
export function setChromeLocale(locale) {
  const next = normalizedLocale(locale);
  if (next === activeLocale) return false;
  activeLocale = next;
  return true;
}

export function tr(key, params = {}) {
  const values = CHROME_TRANSLATIONS[key];
  if (!values) throw new RangeError(`Unknown Parent chrome translation: ${key}`);
  const source = values[activeLocale];
  if (typeof source !== "string" || !source) {
    throw new RangeError(`Missing ${activeLocale} Parent chrome translation: ${key}`);
  }
  return source.replace(/\{([a-z_]+)\}/g, (_token, name) => {
    if (!Object.hasOwn(params, name)) throw new RangeError(`Missing translation parameter: ${name}`);
    return String(params[name]);
  });
}

export function renderChromeTranslations(root = document) {
  // Static DOM labels only: never turn API strings into executable markup.
  const set = (node) => {
    if (node.dataset.i18n) node.textContent = tr(node.dataset.i18n);
    if (node.dataset.i18nAria) node.setAttribute("aria-label", tr(node.dataset.i18nAria));
    if (node.dataset.i18nTitle) node.setAttribute("title", tr(node.dataset.i18nTitle));
  };
  if (root instanceof Element && root.matches("[data-i18n], [data-i18n-aria], [data-i18n-title]")) set(root);
  for (const node of root.querySelectorAll("[data-i18n], [data-i18n-aria], [data-i18n-title]")) set(node);
  if (root === document) document.documentElement.lang = activeLocale;
}
